import { Stream } from './stream';
import { getLogFunction } from '../logger';
const log = getLogFunction('breadcrumbs', 'breadcrumbs.ts');
export class Breadcrumbs {
    constructor() {
        this.breadcrumbSets = [];
        this.defaultClickHandler = function (breadcrumb, e) {
            //no-op -> Let the link do it's thing.
        };
        this.changeStream = new Stream();
    }
    //Turn on the breadcrumbs for the MFE
    turnOnBreadcrumbsFor(breadCrumbSetName) {
        log(`breadcrumbController - turnOnBreadcrumbsFor('${breadCrumbSetName}')`);
        //First see if the breadcrumbs are in there already.
        const newBreadcrumbStack = this.breadcrumbSets.slice();
        const existingIndex = newBreadcrumbStack.findIndex((mfeBreadcrumbs) => {
            return mfeBreadcrumbs.name === breadCrumbSetName;
        });
        if (existingIndex < 0) {
            newBreadcrumbStack.push({
                name: breadCrumbSetName,
                breadcrumbs: [] //Empty array here that will get set later.
            });
        }
        this.breadcrumbSets = newBreadcrumbStack;
    }
    //Sets the breadcrumbs for an MFE
    setBreadcrumbs(setName, breadcrumbs) {
        log(`breadcrumbController - setBreadcrumbs('${setName}')`, breadcrumbs);
        //First see if the breadcrumbs are in there already.
        const newBreadcrumbStack = this.breadcrumbSets.slice();
        const existingIndex = newBreadcrumbStack.findIndex((breadcrumbSet) => {
            return breadcrumbSet.name === setName;
        });
        if (existingIndex >= 0) {
            const newBreadcrumbSet = {
                name: setName,
                breadcrumbs: breadcrumbs.map((breadcrumb) => {
                    if (typeof breadcrumb.onUserClick !== 'function') {
                        const newBreadcrumb = Object.assign({}, breadcrumb, {
                            onUserClick: (e) => {
                                this.defaultClickHandler(newBreadcrumb, e);
                            }
                        });
                        return newBreadcrumb;
                    }
                    return breadcrumb;
                })
            };
            newBreadcrumbStack.splice(existingIndex, 1, newBreadcrumbSet);
            this.breadcrumbSets = newBreadcrumbStack;
            this.changeStream.fire(this.getBreadcrumbs());
        }
    }
    setDefaultBreadcrumbClickHandler(handler) {
        log('breadcrumbController - setDefaultBreadcrumbClickHandler()');
        this.defaultClickHandler = handler;
    }
    //Turn off the breadcrumbs for the MFE
    turnOffBreadcrumbsFor(setName) {
        log(`breadcrumbController - turnOffBreadcrumbsForMfe('${setName}')`);
        const newBreadcrumbStack = this.breadcrumbSets.slice();
        const existingIndex = newBreadcrumbStack.findIndex((mfeBreadcrumbs) => {
            return mfeBreadcrumbs.name === setName;
        });
        if (existingIndex >= 0) {
            newBreadcrumbStack.splice(existingIndex, 1); //Remove the element
            this.breadcrumbSets = newBreadcrumbStack;
        }
        this.changeStream.fire(this.getBreadcrumbs());
    }
    getBreadcrumbs() {
        log('breadcrumbController - getBreadcrumbs()');
        const breadcrumbs = this.breadcrumbSets.map((breadcrumbSet) => {
            return breadcrumbSet.breadcrumbs;
        }).flat();
        log('breadcrumbController - returning', breadcrumbs);
        return breadcrumbs;
    }
}
